    (24, "输出数字 1 到 20 的因式提示。", "for n in range(1, 21):\n    if n % 2 == 0 and n % 5 == 0:\n        print(f\"{n}: both\")\n    elif n % 2 == 0:\n        print(f\"{n}: even\")\n    elif n % 5 == 0:\n        print(f\"{n}: five\")\n    else:\n        print(f\"{n}: other\")", "填空分类输出。", "for n in range(1, 21):\n    if n % 2 == 0 and n % 5 == 0:\n        print(f\"{n}: both\")\n    elif n % 2 == 0:\n        print(f\"{n}: even\")\n    elif n % 5 == 0:\n        print(f\"{n}: five\")\n    else:\n        print(f\"{n}: other\")"),
