    (20, "求 1 到 100 的阶乘和（大数）。", "def fact(n):\n    result = 1\n    for i in range(2, n + 1):\n        result *= i\n    return result\ntotal = 0\nfor i in range(1, 11):\n    total += fact(i)\nprint(f\"Sum: {total}\")", "填空阶乘和。", "def fact(n):\n    result = 1\n    for i in range(2, n + 1):\n        result *= i\n    return result\ntotal = 0\nfor i in range(1, 11):\n    total += fact(i)\nprint(f\"Sum: {total}\")"),
    (21, "模拟约瑟夫环（for 辅助）。", "people = list(range(1, 7))\nk = 3\nidx = 0\norder = []\nwhile people:\n    idx = (idx + k - 1) % len(people)\n    order.append(people.pop(idx))\nprint(order)", "填空约瑟夫。", "people = list(range(1, 7))\nk = 3\nidx = 0\norder = []\nwhile people:\n    idx = (idx + k - 1) % len(people)\n    order.append(people.pop(idx))\nprint(order)"),
